pub open spec fn cpu_default_suspend_spec(result: PsciReturnCode, entry_point_address: UInt64, context_id: UInt64, old_s: S, new_s: S) -> bool {
    (EntryPointAddressIsInvalid(old_s, entry_point_address) ==> result == PSCI_INVALID_ADDRESS)
    && (!EntryPointAddressIsInvalid(old_s, entry_point_address) ==> result == PSCI_SUCCESS)
}

pub open spec fn cpu_freeze_spec(result: PsciReturnCode, old_s: S, new_s: S) -> bool {
    (!CpuFreezeImplemented(old_s) ==> (result == NOT_SUPPORTED && new_s == old_s))
    && ((CpuFreezeImplemented(old_s) && CpuOffDenied(old_s)) ==> (result == DENIED && new_s == old_s))
    && ((CpuFreezeImplemented(old_s) && !CpuOffDenied(old_s)) ==> (result != NOT_SUPPORTED && result != DENIED))
}

pub open spec fn cpu_off_spec(result: PsciReturnCode, old_s: S, new_s: S) -> bool {
    (IsTrustedOsResidentCore(old_s) ==> result == PSCI_DENIED)
    && (!IsTrustedOsResidentCore(old_s) ==> IsCallingCorePoweredDown(new_s))
}

pub open spec fn mem_protect_spec(enable: UInt32, result: i32, old_s: S, new_s: S) -> bool {
    (!MemProtectImplemented(old_s) ==> (result == NOT_SUPPORTED
        && MemProtectEnabled(new_s) == MemProtectEnabled(old_s)))
    && (MemProtectImplemented(old_s) ==> (
        (!MemProtectEnabled(old_s) ==> result == 0)
        && (MemProtectEnabled(old_s) ==> result == 1)
        && ((enable != 0) ==> MemProtectEnabled(new_s))
        && ((enable == 0) ==> !MemProtectEnabled(new_s))
    ))
}

pub open spec fn mem_protect_check_range_spec(base: UInt64, length: UInt64, result: PsciReturnCode, old_s: S, new_s: S) -> bool {
    (!MemProtectRangeIsProtected(old_s, base, length) ==> (result == DENIED && new_s == old_s))
    && (MemProtectRangeIsProtected(old_s, base, length) ==> (result == SUCCESS && new_s == old_s))
}

pub open spec fn migrate_info_type_spec(result: i64, old_s: S, new_s: S) -> bool {
    (result == 0 || result == 1 || result == 2 || result == -1)
    && (result == TrustedOsMigrateInfoType(old_s))
    && (TrustedOsMigrateInfoType(new_s) == TrustedOsMigrateInfoType(old_s))
    && (new_s == old_s)
}

pub open spec fn psci_features_spec(old_s: S, new_s: S, psci_func_id: UInt32, result: Bits64) -> bool {
    true
}

pub open spec fn psci_stat_count_spec(target_cpu: UInt64, power_state: UInt32, result: UInt64, old_s: S, new_s: S) -> bool {
    (!IsValidPsciStatNodeAndState(old_s, target_cpu, power_state) ==> result == 0)
    && (IsValidPsciStatNodeAndState(old_s, target_cpu, power_state) ==> (result == PsciStatCountOf(old_s, target_cpu, power_state) && new_s == old_s))
}

pub open spec fn psci_stat_residency_spec(target_cpu: u64, power_state: u32, result: u64, old_s: S, new_s: S) -> bool {
    (!PsciStatNodeStateIsValid(old_s, target_cpu, power_state) ==> result == 0)
    && (new_s == old_s)
}

pub open spec fn psci_version_spec(result: UInt32, old_s: S, new_s: S) -> bool {
    true
}

pub open spec fn system_off2_spec(hibernate_type: UInt32, cookie: UInt64, result: PsciReturnCode, old_s: S, new_s: S) -> bool {
    (!IsSystemOff2Implemented(old_s) ==> (result == NOT_SUPPORTED && new_s == old_s))
    && ((IsSystemOff2Implemented(old_s) && !SystemOff2ParamsValid(old_s, hibernate_type, cookie)) ==> (result == INVALID_PARAMETERS && new_s == old_s))
    && ((IsSystemOff2Implemented(old_s) && SystemOff2ParamsValid(old_s, hibernate_type, cookie)) ==> (SystemHibernateStateSaved(old_s, new_s) && SystemPoweredOff(new_s)))
}

pub open spec fn system_reset_spec(old_s: S, new_s: S) -> bool {
    true
}

pub open spec fn system_reset_spec(caller: Caller, old_s: S, new_s: S) -> bool {
  (SystemColdResetPerformed(new_s, MachineViewOf(new_s, caller)) &&
   (!CallIsVirtualized(old_s) ==> SystemPowerCycled(new_s)))
}
